const exampleText=obj=>obj?.[MabatI18n.lang]||obj?.he||obj?.en||'';
function exampleCard(ex){
  const kinds={project:B('פרויקט מלא','Complete project'),pack:B('ערכת מונחים לאימוץ','Term pack to adopt from'),vocabulary:B('אוצר מילים לאימוץ','Vocabulary to adopt from'),sources:B('רשימת מקורות','Source list')};
  const label=ex.kind==='project'?B('פתיחת הדוגמה','Open this example'):ex.kind==='sources'?B('הצגת המקורות','Show the sources'):B('הצגה ובחירת ערכים','Show and choose terms');
  return `<article class="discovery-card"><div><span class="badge kind">${esc(kinds[ex.kind]||ex.kind)}</span>${ex.termCount?`<span class="badge">${ex.termCount} ${B('מונחים','terms')}</span>`:''}${ex.license?`<span class="badge">${esc(ex.license)}</span>`:''}<br><b>${esc(exampleText(ex.title))}</b></div>${exampleText(ex.description)?`<p>${esc(exampleText(ex.description))}</p>`:''}${ex.credit?`<p class="small muted">${B('קרדיט','Credit')}: ${esc(ex.credit)}</p>`:''}<div class="discovery-card-actions">${btn('open-example',label,'primary',`data-id="${esc(ex.id)}"`)}${ex.source?link(ex.source,B('מקור החומר','Source of the material')):''}</div></article>`;
}
function examplesDialog(){
  const list=window.MabatExamples||[],groups=window.MabatExampleGroups||[];
  const known=new Set(groups.map(g=>g.id)),loose=list.filter(ex=>!known.has(ex.group));
  const section=(title,note,items)=>items.length?`<section class="example-group"><h3>${esc(title)}</h3>${note?`<p class="notice">${esc(note)}</p>`:''}${items.map(exampleCard).join('')}</section>`:'';
  openDialog(`<h2>${B('דוגמאות','Examples')}</h2><p class="small">${B('חומרים מוכנים להתנסות ולהתחלה מהירה: פרויקט מלא לפתיחה, ערכות מונחים שמציגים ובוחרים מהן מה לאמץ, ורשימות מקורות. דוגמה לא משנה דבר עד שתבחרו לפתוח אותה, ואין חובה להשתמש בה.','Ready-made material for trying things out and for a quick start: a complete project to open, term packs you browse and adopt from, and source lists. An example changes nothing until you choose to open it, and you never have to use one.')}</p>${groups.map(g=>section(exampleText(g.title),exampleText(g.note),list.filter(ex=>ex.group===g.id))).join('')}${section(B('דוגמאות נוספות','More examples'),'',loose)}${list.length?'':`<p class="notice">${B('אין דוגמאות כרגע.','No examples yet.')}</p>`}<div class="toolbar" style="justify-content:flex-end;margin-top:16px"><button data-action="close-dialog">${B('סגירה','Close')}</button></div>`);
}
async function openExample(id,confirmed=false){
  const ex=(window.MabatExamples||[]).find(x=>x.id===id);if(!ex)return;
  if(ex.kind==='project'){
    const hasWork=P.images.length||P.concepts.length||P.annotations.length||P.claims.length;
    if(hasWork&&!confirmed){
      openDialog(`<h2>${B('להחליף את הפרויקט הנוכחי?','Replace the current project?')}</h2><p>${B('פתיחת הדוגמה תחליף את מה שנמצא עכשיו בפרויקט. אפשר לחזור עם ״ביטול״, אבל מומלץ להוריד גיבוי קודם.','Opening the example replaces what is in the project now. Undo can bring it back, but a backup first is safer.')}</p><div class="toolbar">${btn('open-example-confirmed',B('פתיחת הדוגמה','Open the example'),'primary',`data-id="${esc(id)}"`)}${btn('export-project',B('הורדת גיבוי קודם','Download a backup first'))}${btn('examples',B('חזרה לדוגמאות','Back to examples'))}</div>`);
      return;
    }
    importMode='open';closeDialog();
    await loadProject(new File([JSON.stringify(ex.data)],ex.id+'.json',{type:'application/json'}));
    ui.tab='collection';render();
  }else if(ex.kind==='pack'){
    const pack=JSON.parse(JSON.stringify(ex.data));pack.fetchedAt=C.now();
    previewPack(pack,exampleText(ex.title),ex.source||'');
    toast(B('הערכה נטענה לתצוגה מקדימה. בחרו אילו ערכים לאמץ.','The pack is loaded for preview. Choose which terms to adopt.'));
  }else if(ex.kind==='vocabulary'){
    const pack=/\.csv$/i.test(ex.file||'')?MabatOntology.csv(ex.text):MabatOntology.parse(ex.text,ex.file||'vocabulary.json');
    pack.fetchedAt=C.now();pack.license=ex.license||pack.license||'';pack.labels={he:ex.title?.he||'',en:ex.title?.en||''};
    previewPack(pack,exampleText(ex.title),ex.source||'');
    toast(B('הדוגמה נטענה לתצוגה מקדימה. בחרו אילו ערכים לאמץ.','The example is loaded for preview. Choose which terms to adopt.'));
  }else if(ex.kind==='sources'){
    for(const c of ex.connections||[])if(!sessionConnections.some(s=>s.url===c.url))sessionConnections.push({id:C.uid(),labels:c.labels||{},url:c.url,format:c.format||'auto'});
    connectionsDialog();
  }
}

/* ---------- Beginner guide: leads a new user from step to step ---------- */
