  return `<details id="guide" class="guide" ${ui.guideOpen===true?'open':''}><summary><b>${B('מדריך למתחילים','Beginner’s guide')}</b> · ${label}</summary><ol class="guide-steps">${steps.map((s,i)=>`<li class="${s.done?'done':i===current?'current':''}"><span class="gmark">${s.done?'✓':i+1}</span><div><button class="linklike" data-action="guide-focus" data-step="${s.id}"><b>${s.title}</b></button>${s.id===focusId?`<p>${s.body}</p><div class="toolbar">${s.goAction?btn(s.goAction,s.go,'primary'):btn('guide-go',s.go,'primary',`data-step="${s.id}"`)}${s.alt?btn(s.altAction,s.alt):''}</div>`:''}</div></li>`).join('')}</ol><p class="small muted">${B('המדריך מתעדכן לבד לפי מה שכבר עשיתם. אפשר לסגור אותו ולפתוח מחדש בכל רגע.','The guide updates itself as you work. Close or reopen it at any time.')}</p></details>`;
