/* ---------- Search-term translation (Hebrew -> English), terms only ---------- */
function heNormalize(s){return String(s||'').replace(/[\u0591-\u05C7]/g,'').replace(/["״'׳]/g,'').replace(/[־\-–]/g,' ').replace(/\s+/g,' ').trim();}
const glossaryIndex=(()=>{const m=new Map();for(const [k,v] of Object.entries(window.MabatGlossary||{}))m.set(heNormalize(k),v);return m;})();
const heStopwords=new Set(['של','את','עם','על','אל','בין','או','גם','כי','זה','זו','אשר','לא','הוא','היא','אני','אנו','מה','איך','האם','למה','כל','כמו','מתוך','לפי','כדי','עד','יש','אין','אבל','כך','אותו','אותה','הם','הן']);
function glossaryLookup(word){
  const w=heNormalize(word);
  if(glossaryIndex.has(w))return glossaryIndex.get(w);
  const stems=x=>{const out=[x];if(/ים$/.test(x)){out.push(x.slice(0,-2),x.slice(0,-2)+'ה');}if(/ות$/.test(x)){out.push(x.slice(0,-2),x.slice(0,-2)+'ה',x.slice(0,-2)+'ת');}if(/ית$/.test(x))out.push(x.slice(0,-2));return out;};
  for(const p of ['','ה','ו','ב','ל','מ','כ','ש','וה','וב','ול','ומ','שה','מה','לה','בה','כה']){
    if(p&&!w.startsWith(p))continue;
    const rest=w.slice(p.length);if(rest.length<2)continue;
    for(const c of stems(rest))if(glossaryIndex.has(c))return glossaryIndex.get(c);
  }
  return '';
}
function translatePhrase(phrase){
  const words=heNormalize(phrase).split(' ').filter(Boolean),found=[],missing=[];
  for(let i=0;i<words.length;){
    let hit=null;
    for(let n=Math.min(3,words.length-i);n>=1&&!hit;n--){const part=words.slice(i,i+n).join(' '),en=glossaryLookup(part);if(en)hit={he:part,en,n};}
    if(hit){found.push({he:hit.he,en:hit.en,via:'glossary'});i+=hit.n;}
    else{const w=words[i];if(hasHebrewText(w)&&w.length>2&&!heStopwords.has(w)&&!heStopwords.has(w.replace(/^[והבלמכש]/,'')))missing.push(w);i++;}
  }
  return {found,missing};
}
async function chromeTranslate(texts,allowDownload=false){
  try{
    if(typeof Translator==='undefined'||!texts.length)return null;
    const opts={sourceLanguage:'he',targetLanguage:'en'};
    const state=await Promise.race([Translator.availability(opts),new Promise(r=>setTimeout(()=>r('unavailable'),2500))]);
    if(state==='unavailable'||(state!=='available'&&!allowDownload))return null;
    if(state!=='available'){discoveryState.busy=B('Chrome מוריד פעם אחת מודל תרגום (עד חצי דקה)…','Chrome is downloading a translation model once (up to 30 seconds)…');discoveryDialog();}
    const tr=await Promise.race([Translator.create(opts),new Promise((_,no)=>setTimeout(()=>no(Error('timeout')),state==='available'?8000:30000))]);
    const out=[];
    for(const t of texts)out.push(String(await Promise.race([tr.translate(t),new Promise((_,no)=>setTimeout(()=>no(Error('timeout')),8000))])).trim());
    tr.destroy?.();
    return out;
  }catch{return null;}
  finally{if(discoveryState.busy&&/Chrome/.test(discoveryState.busy)){discoveryState.busy='';}}
}
async function translateSearchTerms(auto=false){
  captureDiscoveryInputs();
  const items=[],missing=[];
  for(const [text,report] of [[discoveryState.domain,true],[discoveryState.keywords,true],[discoveryState.question,false]]){
    if(!hasHebrewText(text))continue;
    for(const segment of queryParts(text)){const r=translatePhrase(segment);items.push(...r.found);if(report)missing.push(...r.missing);}
  }
  let remaining=[...new Set(missing)],viaChrome=false;
  if(remaining.length){
    const out=await chromeTranslate(remaining,!auto);
    if(out){const still=[];remaining.forEach((w,i)=>{if(out[i]&&!hasHebrewText(out[i])){items.push({he:w,en:out[i].toLowerCase(),via:'chrome'});viaChrome=true;}else still.push(w);});remaining=still;}
  }
  const existing=queryParts(discoveryState.englishKeywords),have=new Set(existing.map(x=>x.toLowerCase())),added=[];
  for(const it of items)for(const en of it.en.split('|')){if(!have.has(en.toLowerCase())){have.add(en.toLowerCase());existing.push(en);added.push(it);}}
  discoveryState.englishKeywords=existing.join('; ');
  discoveryState.translation={items:[...new Map(items.map(x=>[x.he,x])).values()],missing:remaining,viaChrome,viaGlossary:items.some(x=>x.via==='glossary'),auto};
  if(!auto)discoveryDialog();
}
function renderTranslationNotice(){
  const t=discoveryState.translation;if(!t||(!t.items.length&&!t.missing.length))return '';
  const via=[t.viaGlossary?B('מילון מובנה','built-in glossary'):'',t.viaChrome?B('תרגום מובנה של Chrome','Chrome built-in translation'):''].filter(Boolean).join(' + ');
  return `<div class="notice" role="status">${t.items.length?`<b>${B('תורגם לאנגלית','Translated to English')}${via?` (${via})`:''}:</b> ${esc(t.items.map(x=>`${x.he} → ${x.en}`).join(' · '))}`:''}${t.missing.length?`<br><b>${B('לא תורגמו','Not translated')}:</b> ${esc(t.missing.join(' · '))} — ${B('אפשר להוסיף אותם ידנית באנגלית בשדה האנגלית.','you can add them manually in the English field.')}`:''}<br><span class="small muted">${B('אפשר לערוך את התרגום בשדה האנגלית לפני החיפוש. התרגום משמש רק לחיפוש; נתוני הפרויקט לא משתנים.','You can edit the translation in the English field before searching. It is used for searching only; project data is not changed.')}</span></div>`;
}
/* ---------- Discovery dialog helpers: how-it-works strip and subject map ---------- */
function renderDiscoverySteps(){
  return `<ol class="steps3"><li><b>${B('מחפשים','Search')}</b><span>${B('בוחרים תחום מהמפה, או כותבים מילים. עברית מספיקה — מתרגמים לאנגלית אוטומטית, כי רוב המאגרים באנגלית.','Pick a subject from the map or type words. Hebrew is fine — it is translated to English automatically, because most catalogues are in English.')}</span></li><li><b>${B('בוחרים','Choose')}</b><span>${B('בכל תוצאה כתוב אם יש קובץ שאפשר לטעון. ״קובץ זמין לטעינה״ = אפשר להמשיך מיד.','Each result says whether a file can be loaded. “file available” means you can continue right away.')}</span></li><li><b>${B('טוענים ומאמצים','Load and adopt')}</b><span>${B('הערכים נטענים לתצוגה זמנית. מסמנים את המונחים שרוצים ולוחצים ״אימוץ״ — רק הם נכנסים לפרויקט.','The terms load into a temporary preview. Tick the terms you want and press “Adopt” — only those enter the project.')}</span></li></ol>`;
}
function findTopic(code){
  for(const m of window.MabatTopics||[]){
    if(m.c===code)return {code,he:m.he,en:m.q[0],q:m.q};
    for(const k of m.kids)if(k[0]===code)return {code,he:k[1],en:k[2][0],q:k[2]};
  }
  return null;
}
function renderTopicTree(){
  const topics=window.MabatTopics||[];if(!topics.length)return '';
  const chip=(code,he,en,tip)=>`<button class="chip topic" data-action="pick-topic" data-code="${esc(code)}" title="${esc(tip)}">${esc(B(he,en))} ${/^\d+$/.test(code)?`<small dir="ltr">DDC ${esc(code)}</small>`:''}</button>`;
  const exampleBlock=(window.MabatExamples||[]).filter(ex=>ex.group==='comics-holocaust'&&(ex.kind==='pack'||ex.kind==='project'));
  const picked=discoveryState.ddc?`<p class="small"><b>${B('תחום נבחר','Selected subject')}:</b> ${esc(discoveryState.ddc.label)} <small dir="ltr">DDC ${esc(discoveryState.ddc.code)}</small> ${btn('clear-topic','✕','',`aria-label="${B('ניקוי התחום','Clear subject')}"`)}</p>`:'';
  return `<details class="topic-tree" ${discoveryState.searched?'':'open'}><summary><b>${B('מפת תחומים','Subject map')}</b> — ${B('לא בטוחים מה לחפש? בחרו תחום','not sure what to search? pick a subject')}</summary><p class="small muted">${B('המפה מבוססת על סיווג דיואי (DDC), שבו BARTOC מסווג כל אוצר מילים. בחירת תחום ממלאת את שדות החיפוש ומחפשת; היא אינה מוסיפה דבר לפרויקט.','The map follows the Dewey Decimal Classification (DDC), which BARTOC uses to classify every vocabulary. Choosing a subject fills in the search fields and searches; it adds nothing to the project.')}</p><div class="topic-grid">${topics.filter(m=>!m.example).map(m=>`<details class="topic-main"><summary>${esc(B(m.he,m.q[0]))} <small dir="ltr">DDC ${esc(m.c)}</small></summary><div class="chips">${chip(m.c,B('כל התחום: ','Whole field: ')+m.he,'Whole field: '+m.q[0],m.q.join(', '))}${m.kids.map(k=>chip(k[0],k[1],k[2][0],k[2].join(', '))).join('')}</div></details>`).join('')}${topics.filter(m=>m.example).map(m=>`<details class="topic-main topic-example"><summary>${esc(B(m.he,m.q[0]))} <span class="badge kind">${B('דוגמה','Example')}</span></summary><p class="small muted">${B('נושא לדוגמה מן הגרסה הקודמת. אפשר לחפש ברשת מונחים בנושא, או לפתוח ערכות מוכנות ולאמץ מהן. זו דוגמה בלבד.','A topic example from the previous version. You can search the web for terms on this topic, or open ready-made packs and adopt from them. It is an example only.')}</p><div class="chips">${chip(m.c,B('חיפוש ברשת: ','Search the web: ')+m.he,'Search the web: '+m.q.join(', '),m.q.join(', '))}${exampleBlock.filter(ex=>ex.kind==='pack').map(ex=>`<button class="chip topic" data-action="open-example" data-id="${esc(ex.id)}" title="${esc(exampleText(ex.description))}">${esc(exampleText(ex.title))} <small>${ex.termCount||''}</small></button>`).join('')}</div></details>`).join('')}</div></details>${picked}`;
}
async function queryBartocDdc(code){
  const url=new URL(`${discoveryApis.bartoc}/voc`);
  url.searchParams.set('subject',`http://dewey.info/class/${code}/e23/`);url.searchParams.set('limit','15');
  return responseItems(await fetchDiscoveryJSON(url.href)).map(item=>discoveryResult(item,'bartoc'));
}
async function pickTopic(code){
  const t=findTopic(code);if(!t)return;
  captureDiscoveryInputs();
  const label=B(t.he,t.en);
  Object.assign(discoveryState,{domain:label,question:'',keywords:'',englishKeywords:t.q.join('; '),ddc:/^\d+$/.test(t.code)?{code:t.code,label}:null,translation:null});
  discoveryDialog();
  await searchDiscoveries();
}
function connectionsDialog(){const rows=sourceConnections().map(s=>`<div class="connection-row"><b>${esc(L(s))}</b><p class="source-details">${esc(s.url)}</p><div class="toolbar">${btn('load-connection',B('טעינה מקוונת','Load online'),'primary',`data-id="${esc(s.id)}"`)}${btn('custom-connection',B('שינוי כתובת','Edit URL'),'',`data-id="${esc(s.id)}"`)}</div></div>`).join('');openDialog(`<h2>${B('מקורות וחיבורים','Sources and connections')} ${infoButton('connections')}</h2><p>${B('אין במערכת מקורות נושאיים טעונים מראש. חפשו בקטלוגים הכלליים, או הוסיפו קישור לקובץ נתונים לפי הצורך.','No topic-specific sources are preloaded. Search general catalogues or add a data-file URL when needed.')}</p><div class="scroll">${rows||`<p>${B('אין מקורות מותאמים כרגע.','No custom sources yet.')}</p>`}${link('https://bartoc.org','BARTOC')} · ${link('https://lov.linkeddata.es/dataset','LOV')} · ${link('https://www.ebi.ac.uk/ols4','OLS')}</div><div class="toolbar">${btn('custom-connection',B('＋ מקור מותאם אישית','＋ Custom source'),'primary')}${btn('import-vocab',B('ייבוא קובץ מהמחשב','Import a local file'))}</div><p class="notice">${B('אם הדפדפן חוסם קריאה מאתר המקור, הורידו את קובץ הנתונים וייבאו אותו מקומית. הנתונים שאומצו נשארים במודל הפרויקט.','If the browser blocks a source, download its data file and import it locally. Adopted data remains in the project model.')}</p>`);}
function customConnection(id){const s=sourceConnections().find(s=>s.id===id);openDialog(`<h2>${B('מקור אונטולוגיה נוסף','Another ontology source')}</h2><form id="sourceForm" class="stack"><div class="bi-pair"><label dir="rtl">${T("שם בעברית")}<input id="sourceNameHe" value="${esc(F(s,'label','he'))}"></label><label dir="ltr">English name<input id="sourceNameEn" value="${esc(F(s,'label','en'))}"></label></div><label>${B('כתובת קובץ נתונים (HTTPS)','Data file URL (HTTPS)')}<input id="sourceURL" required type="url" dir="ltr" value="${esc(s?.url)}" placeholder="https://example.org/vocabulary.ttl"></label><label>${B('פורמט','Format')}<select id="sourceFormat">${['auto','rdf','ttl','jsonld','json','csv','nt'].map(k=>opt(k,k,s?.format||'auto')).join('')}</select></label><button class="primary">${B('טעינה להפעלה זו','Load for this session')}</button></form>`,()=>{$('sourceForm').onsubmit=async e=>{e.preventDefault();const url=$('sourceURL').value.trim();if(!safeURL(url)||!url.startsWith('https://')||new URL(url).username||new URL(url).password){toast(B('נדרשת כתובת HTTPS תקינה.','A valid HTTPS URL is required.'));return;}const entry={id:C.uid(),labels:{he:$('sourceNameHe').value.trim(),en:$('sourceNameEn').value.trim()},url,format:$('sourceFormat').value};if(!entry.labels.he&&!entry.labels.en)entry.labels.en=new URL(url).hostname;sessionConnections.push(entry);await loadConnection(entry);};});}
let ontologyBusy=false;
async function fetchOntology(url,format='auto',fetcher=fetch){const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)throw Error(B('נדרשת כתובת HTTPS ללא פרטי כניסה.','Use an HTTPS URL without credentials.'));const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),22000),max=20*1024*1024;try{const response=await fetcher(u.href,{mode:'cors',credentials:'omit',signal:controller.signal,headers:{Accept:'application/rdf+xml, text/turtle, application/ld+json, application/json, text/csv;q=0.9'}});if(!response.ok)throw Error('HTTP '+response.status);if(Number(response.headers.get('content-length'))>max)throw Error(B('הקובץ גדול מ־20MB; ייבאו מקטע קטן יותר.','The file exceeds 20MB; import a smaller subset.'));let text;if(response.body?.getReader){const reader=response.body.getReader(),decoder=new TextDecoder();let size=0,parts=[];while(true){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>max){await reader.cancel();throw Error(B('הקובץ גדול מ־20MB.','The file exceeds 20MB.'));}parts.push(decoder.decode(value,{stream:true}));}parts.push(decoder.decode());text=parts.join('');}else{text=await response.text();if(new TextEncoder().encode(text).length>max)throw Error('File exceeds 20MB');}if(/^\s*(<!doctype html|<html)/i.test(text))throw Error(B('הכתובת החזירה עמוד HTML. הזינו קישור לקובץ הנתונים.','The URL returned an HTML page. Supply a data-file URL.'));const ct=response.headers.get('content-type')||'',extension=format!=='auto'?format:/turtle/.test(ct)?'ttl':/rdf\+xml|application\/xml/.test(ct)?'rdf':/json/.test(ct)?'jsonld':/csv/.test(ct)?'csv':u.pathname.split('.').pop();return {pack:extension==='csv'?MabatOntology.csv(text):MabatOntology.parse(text,'ontology.'+extension,u.href),text};}finally{clearTimeout(timeout);}}
function previewPack(pack,name,source=''){pack.id=C.uid();pack.name=name||pack.name;pack.source=source||pack.source||'';pack.labels??={he:/[\u0590-\u05ff]/.test(pack.name)?pack.name:'',en:!/[\u0590-\u05ff]/.test(pack.name)?pack.name:''};pack.notes??={he:'תצוגה מקדימה זמנית. בחרו אילו ערכים לאמץ לפרויקט.',en:'Temporary preview. Choose which terms to adopt into the project.'};sessionPacks.push(pack);ui.pack=pack.id;ui.packSelection=[];ui.catalogQuery='';ui.catalogPage=0;ui.model='library';ui.tab='model';closeDialog();render();return pack;}
async function loadConnection(source){if(ontologyBusy)return;ontologyBusy=true;openDialog(`<h2>${B('טוען מקור…','Loading source…')}</h2><p>${esc(L(source)||source.url)}</p><p class="progress">${B('הנתונים הקיימים נשמרים בזמן הטעינה.','Existing data is retained while loading.')}</p>`);try{const {pack}=await fetchOntology(source.url,source.format);pack.fetchedAt=C.now();pack.labels=source.labels||{};previewPack(pack,L(source)||new URL(source.url).hostname,source.url);toast(B('המקור נטען בהצלחה. בחרו ערכים לאימוץ.','Source loaded successfully. Choose terms to adopt.'));}catch(e){openDialog(`<h2>${B('לא ניתן לטעון את המקור','Could not load source')}</h2><p>${esc(e.message)}</p><p>${B('ייתכן שהמקור אינו זמין או חוסם CORS. הורידו את קובץ הנתונים וייבאו אותו מקומית. נתוני הפרויקט לא שונו.','The source may be unavailable or block CORS. Download its data file and import locally. Project data was not changed.')}</p><div class="toolbar">${link(source.url,B('פתיחת קובץ המקור','Open source file'))}${btn('import-vocab',B('ייבוא מקובץ','Import from file'))}${btn('connections',B('חזרה למקורות','Back to sources'))}</div>`);}finally{ontologyBusy=false;}}
function exportVocabulary(){const out={format:'mabat-vocabulary',version:2,name:L(P,'name'),groups:C.clone(P.groups),conceptLinks:C.clone(P.conceptLinks),terms:[...P.concepts.map(c=>({...C.clone(c),group:groupOf(c)?.label,groupLabels:groupOf(c)?.i18n?.label||groupOf(c)?.labels||{},layer:groupOf(c)?.layer,selection:groupOf(c)?.selection,groupColor:groupOf(c)?.color})),...P.relationTypes.map(r=>({...C.clone(r),relationKind:r.kind,kind:'relation'}))]};downloadBlob(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),slug()+'.vocabulary.json');}
function enhanceView(){updateChrome();decorateHelp();for(const el of document.querySelectorAll('[data-pack-term]'))el.onchange=()=>{const set=new Set(ui.packSelection||[]);el.checked?set.add(el.dataset.packTerm):set.delete(el.dataset.packTerm);ui.packSelection=[...set];};for(const el of document.querySelectorAll('[data-im-field][data-im-lang]'))el.onchange=()=>mutate(B('עדכון שדה דו־לשוני בתמונה','Update bilingual image field'),()=>{setBiField(P.images.find(im=>im.id===el.dataset.id),el.dataset.imField,el.dataset.imLang,el.value.trim());});if($('catalogQuery'))$('catalogQuery').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();actions['catalog-search']();}};if($('catalogKind'))$('catalogKind').onchange=()=>{ui.catalogKind=$('catalogKind').value;ui.catalogPage=0;render();};if($('catalogParents'))$('catalogParents').onchange=()=>{ui.includeParents=$('catalogParents').checked;};if($('catalogGraph'))$('catalogGraph').ontoggle=()=>{ui.catalogGraph=$('catalogGraph').open;};}
Object.assign(actions,{
info:el=>showInfo(el.dataset.topic),connections:connectionsDialog,'custom-connection':el=>customConnection(el.dataset.id),'load-connection':el=>loadConnection(sourceConnections().find(s=>s.id===el.dataset.id)),'discover-ontologies':discoveryDialog,'run-discovery-search':searchDiscoveries,'review-discovery-result':el=>reviewDiscoveryResult(Number(el.dataset.index)),'load-discovery-url':el=>loadDiscoveryURL(Number(el.dataset.index)),'quick-load-discovery':el=>quickLoadDiscovery(Number(el.dataset.index)),'translate-terms':()=>translateSearchTerms(false),'examples':examplesDialog,'show-examples':examplesDialog,'open-example':el=>openExample(el.dataset.id),'open-example-confirmed':el=>openExample(el.dataset.id,true),'pick-topic':el=>pickTopic(el.dataset.code),'clear-topic':()=>{captureDiscoveryInputs();discoveryState.ddc=null;discoveryDialog();},'guide-focus':el=>{ui.guideStep=el.dataset.step;render();},'guide-go':el=>{const step=guideSteps().find(x=>x.id===el.dataset.step);if(!step)return;ui.guideStep=step.id;if(step.tab)ui.tab=step.tab;render();window.scrollTo?.({top:0,behavior:'smooth'});},'guide-discover':()=>{ui.tab='model';ui.model='library';render();discoveryDialog();},'guide-build':()=>{ui.tab='model';ui.model='edit';render();},'check-discovery-sources':checkDiscoverySources,'close-discovery-details':()=>{discoveryState.selected=null;discoveryDialog();},'close-dialog':closeDialog,
'remove-catalog':el=>{const id=el.dataset.id,pack=sessionPacks.find(p=>p.id===id);if(!pack)return;const adopted=P.concepts.filter(c=>c.sourcePack===id).length+P.relationTypes.filter(r=>r.sourcePack===id).length;openDialog(`<h2>${B('הסרת מקור מהתצוגה','Remove source from view')}</h2><p>${B('המקור','The source')}: <b>${esc(L(pack,'name')||L(pack))}</b></p><p>${B('ההסרה מסלקת את תצוגת המקור הזמנית. הפרויקט אינו שומר את קובץ האונטולוגיה; מושגים שאומצו נשארים כחלק מהמודל.','This clears the temporary source preview. The project does not store the ontology file; adopted concepts remain part of the model.')}${adopted?` ${B(`נמצאו ${adopted} ערכים שאומצו ממקור זה.`,`Found ${adopted} adopted entries from this source.`)}`:''}</p><div class="toolbar"><button id="confirmRemoveCatalog" class="danger">${B('הסרת המקור','Remove source')}</button>${btn('cancel',B('ביטול','Cancel'))}</div>`,()=>{$('confirmRemoveCatalog').onclick=()=>{sessionPacks=sessionPacks.filter(p=>p.id!==id);if(ui.pack===id){ui.pack='empty';ui.packSelection=null;}render();closeDialog();};});},
'choose-pack':el=>{ui.pack=el.dataset.id;ui.packSelection=[];ui.catalogQuery='';ui.catalogKind='';ui.catalogPage=0;render();},
'catalog-search':()=>{ui.catalogQuery=$('catalogQuery').value.trim();ui.catalogPage=0;render();},'catalog-clear':()=>{ui.catalogQuery='';ui.catalogKind='';ui.catalogPage=0;render();},'catalog-prev':()=>{ui.catalogPage=Math.max(0,(ui.catalogPage||0)-1);render();},'catalog-next':()=>{ui.catalogPage=(ui.catalogPage||0)+1;render();},'catalog-select-filtered':()=>{ui.packSelection=[...new Set([...(ui.packSelection||[]),...catalogTerms(currentPack()).map(t=>t.id)])];render();},'pack-all':()=>{ui.packSelection=currentPack().terms.map(t=>t.id);render();},'pack-none':()=>{ui.packSelection=[];render();},
'adopt-pack':()=>{const pack=currentPack();const selected=MabatOntology.selection(pack,ui.packSelection||[],$('catalogParents')?.checked!==false);if(!selected.length){toast(B('בחרו תחילה ערכים.','Select terms first.'));return;}const layer=$('packLayer').value;const ok=mutate(B('אימוץ ערכים מאונטולוגיה','Adopt ontology terms'),()=>C.importTerms(P,pack,selected,layer));if(ok){const r=C.importTerms.lastReport;toast(B(`נוספו ${r.concepts} מושגים ו־${r.relations} סוגי קשרים; ${r.reused} ערכים כבר היו בפרויקט.`,`${r.concepts} concepts and ${r.relations} relation types added; ${r.reused} entries already existed.`));if(r.omittedParents)showInfo('parents');}},
'graph-pack':el=>{const t=currentPack().terms.find(t=>t.id===el.dataset.id);if(!t)return;const by=new Map(currentPack().terms.map(t=>[t.id,t]));openDialog(`<h2 dir="auto">${esc(L(t))}</h2><div class="bi-pair"><div lang="he" dir="rtl"><b>${esc(F(t,'label','he')||'—')}</b><p>${esc(F(t,'definition','he'))}</p></div><div lang="en" dir="ltr"><b>${esc(F(t,'label','en')||'—')}</b><p>${esc(F(t,'definition','en'))}</p></div></div><p>${B('הורים','Broader terms')}: ${(t.parents||[]).map(id=>esc(L(by.get(id))||id)).join(' · ')||'—'}</p>${t.uri?link(t.uri,B('רשומת המקור','Source record')):''}<p class="source-details">${B('מזהה','Identifier')}: ${esc(t.id)}</p>${Object.entries(t.labels||{}).filter(([k])=>!['he','en'].includes(k)).map(([k,v])=>`<p><b>${esc(k)}</b>: ${esc(v)}</p>`).join('')}${t.domain?.length?`<p dir="ltr">domain: ${t.domain.map(esc).join(', ')}</p>`:''}${t.range?.length?`<p dir="ltr">range: ${t.range.map(esc).join(', ')}</p>`:''}${t.mappings?.length?`<p>${B('מיפויים חיצוניים','External mappings')}: ${t.mappings.map(m=>link(m.uri,m.uri)).join(' · ')}</p>`:''}`);}
});
$('uiLanguage').onclick=()=>{MabatI18n.lang=MabatI18n.lang==='he'?'en':'he';MabatI18n.save();if($('dialog').open)closeDialog();render();$('saveStatus').textContent=B('שמירה מקומית · ראו מדריך לפרטים','Local autosave · see guide for details');};$('bilingualDisplay').onchange=()=>{MabatI18n.both=$('bilingualDisplay').checked;MabatI18n.save();render();};for(const lang of ['he','en'])$('projectName'+(lang==='he'?'He':'En')).onchange=()=>mutate(B('עדכון שם הפרויקט','Update project name'),()=>setBiField(P,'name',lang,$('projectName'+(lang==='he'?'He':'En')).value.trim()));
async function readLocalText(file){if(!file||!file.size)throw Error('The selected file is empty.');if(typeof file.text==='function'){try{return (await file.text()).replace(/^\uFEFF/,'');}catch{}}return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||'').replace(/^\uFEFF/,''));reader.onerror=()=>reject(reader.error||Error('Could not read the selected file'));reader.readAsText(file,'UTF-8');});}
$('vocabInput').onchange=async()=>{const file=$('vocabInput').files[0];if(!file)return;try{const text=await readLocalText(file),looksCsv=/^(?:\uFEFF)?(?:label|id|uri|label_he|label_en|pref_?label|prefLabel|term|concept|name|title)[,;\t]/im.test(text.trimStart()),pack=/\.(csv|tsv)$/i.test(file.name)||looksCsv?MabatOntology.csv(text):MabatOntology.parse(text,file.name);previewPack(pack,pack.name==='Imported ontology'?file.name:pack.name||file.name);toast(B('הקובץ נקרא. עיינו בדוח ובחרו ערכים לאימוץ.','File parsed. Inspect the report and choose terms to adopt.'));}catch(e){const detail=String(e?.message||e),tips=B('ייבוא מקומי מקבל קובצי Turtle (.ttl), RDF/XML (.rdf/.owl/.xml), JSON-LD/JSON, SPARQL JSON או CSV. צריך לבחור קובץ נתונים עצמו, לא דף HTML ולא רשומת קטלוג. בקובץ JSON-LD עם הקשר מרוחק, הקשר לא נטען אוטומטית.','Local import accepts Turtle (.ttl), RDF/XML (.rdf/.owl/.xml), JSON-LD/JSON, SPARQL JSON, or CSV. Choose the data file itself, not an HTML page or registry record. Remote JSON-LD contexts are not fetched automatically.');openDialog(`<h2>${B('ייבוא הקובץ נכשל','File import failed')}</h2><p><b>${esc(file.name)}</b></p><p>${esc(detail)}</p><div class="notice"><p>${esc(tips)}</p></div><p>${B('הקובץ לא נוסף לפרויקט. נסו לייצא אותו בפורמט נתמך, או שלחו לי את הקובץ והודעת השגיאה כדי שאוכל להתאים את הייבוא.','The file was not added to the project. Try exporting it in a supported format, or share the file and error message so I can adjust the importer.')}</p><div class="toolbar">${btn('import-vocab',B('בחירת קובץ אחר','Choose another file'),'primary')}${btn('close-dialog',B('סגירה','Close'))}</div>`);}finally{$('vocabInput').value='';}};

